/* dibungkus oleh JS Packer (mode Node) — base64 + loader, hanya penghalang baca sekilas, BUKAN enkripsi */
(function () {
  var __p = "";
  var __s = Buffer.from(__p, "base64").toString("utf8");
  eval(__s); // eval langsung (bukan (0,eval)) supaya require/module/__dirname tetap bisa dipakai kode aslinya
})();
